data: {"id":"chatcmpl-2026101215285264068372c955d568eck1PWkG","created":1791818932,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_1e2376aab5d14d9a986a8b41","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Exact branch-and-bound solver for the single-vehicle delivery routing\\nproblem in delivery_data.json (model defined in formulation.md).\\n\\nModel recap:\\n- One vehicle based at depot D, capacity Q = 6.\\n- Total demand (9) exceeds Q, so per the adopted assumption the vehicle may\\n  reload at D mid-route (multi-trip single vehicle). Capacity applies per\\n  excursion between depot visits.\\n- Objective: minimize total travel distance.\\n\\nMethod: depth-first branch-and-bound enumerating all feasible journeys\\n(customer visit sequences with depot reloads). Prunes using an admissible\\nlower bound: each unvisited customer needs at least its cheapest incident\\nedge. Results are cross-checked by independent exhaustive enumeration of\\nall capacity-feasible customer partitions.\\n\\nIn production you would hand the same formulation to OR-Tools/HiGHS; this\\npure-Python search is exact for this instance size.\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom itertools import permutations\\n\\nwith open('delivery_data.json') as f:\\n    data = json.load(f)\\n\\nDEPOT = data['depot']\\nCUSTOMERS = sorted(data['customers'])\\nDEMANDS = data['demands']\\nQ = data['vehicle_capacity']\\nRAW = data['distances']\\nN = [DEPOT] + CUSTOMERS\\n\\n\\ndef d(i, j):\\n    return 0 if i == j else RAW['-'.join(sorted((i, j)))]\\n\\n\\ndef lower_bound(cur, unvisited):\\n    \\\"\\\"\\\"Admissible bound: every unvisited customer requires >= 1 incident\\n    edge; charge each its cheapest incident edge. Eventual return-to-depot\\n    cost is dropped (>= 0), so the bound never overestimates.\\\"\\\"\\\"\\n    return sum(min(d(c, o) for o in N if o != c) for c in unvisited)\\n\\n\\nbest_cost = float('inf')\\nbest_journeys = []\\nexplored = 0\\n\\n\\ndef dfs(cur, load, unvisited, cost, path):\\n    global best_cost, best_journeys, explored\\n    explored += 1\\n    if cost + lower_bound(cur, unvisited) > best_cost:\\n        return  # prune (strict >, so all tied optima are still collected)\\n    if not unvisited:\\n        total = cost + (d(cur, DEPOT) if cur != DEPOT else 0)\\n        end = path + ([DEPOT] if cur != DEPOT else [])\\n        if total < best_cost:\\n            best_cost = total\\n            best_journeys = [end]\\n        elif total == best_cost:\\n            best_journeys.append(end)\\n        return\\n    # Branch 1: drive to a feasible unvisited customer\\n    for c in CUSTOMERS:\\n        if c in unvisited and load + DEMANDS[c] <= Q:\\n            dfs(c, load + DEMANDS[c], unvisited - {c},\\n                cost + d(cur, c), path + [c])\\n    # Branch 2: return to depot to reload (only if someone is left)\\n    if cur != DEPOT and unvisited:\\n        dfs(DEPOT, 0, unvisited, cost + d(cur, DEPOT), path + [DEPOT])\\n\\n\\ndfs(DEPOT, 0, frozenset(CUSTOMERS), 0, [DEPOT])\\n\\n\\n# ---------- report ----------\\nprint('=' * 62)\\nprint('EXACT SOLVER - branch & bound over all feasible journeys')\\nprint('=' * 62)\\nprint(f'Customers: {CUSTOMERS}   demands: {DEMANDS}')\\nprint(f'Capacity Q = {Q}   total demand = {sum(DEMANDS.values())}')\\nif sum(DEMANDS.values()) > Q:\\n    print('Strict single tour (no reload): INFEASIBLE (demand > capacity).')\\n    print('Model allows mid-route reload at depot (see formulation.md).')\\nprint(f'\\\\nSearch tree: {explored} nodes explored (with bound pruning)')\\nprint(f'\\\\nOBJECTIVE VALUE (min total distance) = {best_cost}')\\nprint('\\\\nOPTIMAL DECISION VARIABLES (x_ij = 1 on the arcs below):')\\n\\n\\ndef journey_stats(journey):\\n    arcs, load, u = [], 0, {}\\n    for i in range(len(journey) - 1):\\n        a, b = journey[i], journey[i + 1]\\n        arcs.append((a, b))\\n        if b == DEPOT:\\n            if i + 1 < len(journey) - 1:  # mid-journey depot stop = reload\\n                load = 0\\n        else:\\n            load += DEMANDS[b]\\n            u[b] = load\\n    return arcs, u\\n\\n\\nseen = set()\\nfor journey in best_journeys:\\n    arcs, u = journey_stats(journey)\\n    key = frozenset(arcs)\\n    if key in seen:\\n        continue\\n    seen.add(key)\\n    print(f'\\\\n  Optimal solution {len(seen)}: ' + ' -> '.join(journey))\\n    print('    x_ij = 1 for: ' + ', '.join(f'{a}->{b}' for a, b in arcs))\\n    print('    loads u_i after each customer: '\\n          + ', '.join(f'u_{c}={v}' for c, v in u.items()))\\n    print(f'    depot reloads: {journey.count(DEPOT) - 2}')\\n\\n\\n# ---------- independent cross-check: exhaustive partition enumeration ----------\\ndef tour_cost(group):\\n    return min(\\n        sum(d(a, b) for a, b in zip((DEPOT,) + perm, perm + (DEPOT,)))\\n        for perm in permutations(group)\\n    )\\n\\n\\ndef partitions(items):\\n    if not items:\\n        yield []\\n        return\\n    first, rest = items[0], items[1:]\\n    for p in partitions(rest):\\n        for i in range(len(p)):\\n            yield p[:i] + [p[i] + [first]] + p[i + 1:]\\n        yield [[first]] + p\\n\\n\\nfeasible = [p for p in partitions(CUSTOMERS)\\n            if all(sum(DEMANDS[c] for c in g) <= Q for g in p)]\\ncheck_cost, check_trips = min(\\n    (sum(tour_cost(g) for g in p), p) for p in feasible\\n)\\nprint('\\\\nCROSS-CHECK - exhaustive enumeration of capacity-feasible')\\nprint(f'partitions ({len(feasible)} feasible): optimum = {check_cost}, '\\n      f'trips = {check_trips}')\\nprint(f'Branch-and-bound matches exhaustive check: {check_cost == best_cost}')\\n\",\"path\":\"solver.py\"}"}}]}}]}

